import React, { useState } from "react";
import axios from "axios";
import { Link, useNavigate } from "react-router-dom";

export default function UserSignin({ handleLogin }) {
  const [email, setEmail] = useState("");
  const [error, setError] = useState("");

  const createAuth = async (e) => {
    e.preventDefault();

    try {
      const res = await axios.post("http://localhost:3597/api/user/login", {
        email,
      });
      alert("Login link sent to your email");
      localStorage.setItem("userToken", res.data.token);
      console.log("Token saved:", res.data.token);

      setError("Login successfully!");
    } catch (error) {
      alert(error.response?.data.message || "Please try again");
      setError("Invalid credentials");
    }
  };

  return (
    <div
      className="relative flex flex-col items-center justify-center p-16 h-screen overflow-hidden
      bg-gradient-to-tr from-[#0a2e2a] via-[#431f79] to-[#230c16]
      bg-[length:300%_300%]
      animate-gradientGlow"
    >
       {/* 🔥 EXTRA NEON GLOW LAYER */}
    <div className="
      absolute inset-0
      bg-gradient-to-r from-cyan-400/60 via-purple-500/60 to-pink-500/40
      blur-3xl
      animate-glowPulse
    "></div>
 {/* ⚡ RADIAL GLOW CENTER */}
      <div
        className="absolute inset-0
        bg-[radial-gradient(circle_at_center,rgba(255,255,255,0.35),transparent_70%)]
        animate-glowPulse"
      ></div>

      <div
        className="flex flex-col items-center shadow rounded p-5
      bg-black/40
      backdrop-blur-md"
      >
        <h1 className="font-extrabold">SignIn</h1>
        <form
          onSubmit={createAuth}
          className="flex flex-col mx-auto p-10 gap-4"
        >
          <label htmlFor="email" className="font-semibold">
            Email
            <input
              type="email"
              id="email"
              placeholder="Email"
              className="flex w-[300px] gap-5 p-2 shadow rounded bg-transparent border-l border-b"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </label>

          <button
            type="submit"
            className="
              mt-5  rounded-md
              m-auto w-fit p-2 border-b border-r shadow
              bg-gradient-to-r from-cyan-600 via-slate-500 to-blue-600
               hover:from-cyan-700 hover:to-blue-800
              text-white font-semibold
              transition  hover:scale-105
            "
          >
            Send Login Link
          </button>
          {error && <p className="text-red-500 m-auto">{error}</p>}
        </form>
      </div>
    </div>
  );
}
